// Code node: "Final Assembler"

// HTML → plain text converter
function stripHtml(str) {
  if (!str) return '';
  return str
    .replace(/<div[^>]*style="page-break-after[^"]*"[^>]*><\/div>/gi, '\n---\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<strong>(.*?)<\/strong>/gi, '**$1**')
    .replace(/<em>(.*?)<\/em>/gi, '*$1*')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const prelimPages = stripHtml($('Call Chapter 1 - 3').first().json.output_firstItem);
const abstractRefs = stripHtml($('Call Chapter 1 - 3').first().json.A8_Abstract__References_output_firstItem);
const ch1 = stripHtml($('Call Chapter 1 - 3').first().json.A3_Chapter_1_Writer_output_firstItem);
const ch2 = stripHtml($('Call Chapter 1 - 3').first().json.A4d_Chapter_2_Final_Assembler_output_firstItem);
const ch3 = stripHtml($('Call Chapter 1 - 3').first().json.A5_Chapter_3_Writer_output_firstItem);

const assembled = [
  prelimPages,
  abstractRefs,
  ch1,
  ch2,
  ch3,
].filter(Boolean).join('\n\n---\n\n');

return [{ json: { assembledDocument: assembled } }];

