// --- CRC32 (pure JS) ---
function crc32(buf) {
  var table = crc32.t;
  if (!table) {
    table = crc32.t = new Uint32Array(256);
    for (var i = 0; i < 256; i++) {
      var c = i;
      for (var j = 0; j < 8; j++) {
        c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
      }
      table[i] = c;
    }
  }
  var crc = 0xFFFFFFFF;
  for (var i = 0; i < buf.length; i++) {
    crc = table[(crc ^ buf[i]) & 0xFF] ^ (crc >>> 8);
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

// --- ZIP builder (STORE, no compression) ---
function createZip(files) {
  var entries = [];
  var offset = 0;
  var localParts = [];
  for (var fi = 0; fi < files.length; fi++) {
    var f = files[fi];
    var nameB = Buffer.from(f.name, 'utf-8');
    var data = Buffer.from(f.content, 'utf-8');
    var crc = crc32(data);
    var lh = Buffer.alloc(30 + nameB.length);
    lh.writeUInt32LE(0x04034b50, 0);
    lh.writeUInt16LE(20, 4);
    lh.writeUInt16LE(0, 6);
    lh.writeUInt16LE(0, 8);
    lh.writeUInt16LE(0, 10);
    lh.writeUInt16LE(0, 12);
    lh.writeUInt32LE(crc, 14);
    lh.writeUInt32LE(data.length, 18);
    lh.writeUInt32LE(data.length, 22);
    lh.writeUInt16LE(nameB.length, 26);
    lh.writeUInt16LE(0, 28);
    nameB.copy(lh, 30);
    entries.push({
      nameB: nameB,
      data: data,
      crc: crc,
      offset: offset
    });
    localParts.push(Buffer.concat([lh, data]));
    offset += lh.length + data.length;
  }
  var cdParts = [];
  for (var ei = 0; ei < entries.length; ei++) {
    var e = entries[ei];
    var cd = Buffer.alloc(46 + e.nameB.length);
    cd.writeUInt32LE(0x02014b50, 0);
    cd.writeUInt16LE(20, 4);
    cd.writeUInt16LE(20, 6);
    cd.writeUInt16LE(0, 8);
    cd.writeUInt16LE(0, 10);
    cd.writeUInt16LE(0, 12);
    cd.writeUInt16LE(0, 14);
    cd.writeUInt32LE(e.crc, 16);
    cd.writeUInt32LE(e.data.length, 20);
    cd.writeUInt32LE(e.data.length, 24);
    cd.writeUInt16LE(e.nameB.length, 28);
    cd.writeUInt16LE(0, 30);
    cd.writeUInt16LE(0, 32);
    cd.writeUInt16LE(0, 34);
    cd.writeUInt16LE(0, 36);
    cd.writeUInt32LE(0, 38);
    cd.writeUInt32LE(e.offset, 42);
    e.nameB.copy(cd, 46);
    cdParts.push(cd);
  }
  var cdBuf = Buffer.concat(cdParts);
  var eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);
  eocd.writeUInt16LE(0, 4);
  eocd.writeUInt16LE(0, 6);
  eocd.writeUInt16LE(entries.length, 8);
  eocd.writeUInt16LE(entries.length, 10);
  eocd.writeUInt32LE(cdBuf.length, 12);
  eocd.writeUInt32LE(offset, 16);
  eocd.writeUInt16LE(0, 20);
  return Buffer.concat(
    localParts.concat([cdBuf, eocd])
  );
}

// --- XML helpers ---
function esc(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function makeRuns(text, forceBold) {
  var runs = '';
  var parts = String(text).split(
    /(\*\*[^*]+\*\*|\*[^*]+\*)/g
  );
  for (var i = 0; i < parts.length; i++) {
    var part = parts[i];
    if (!part) continue;
    var isBoldMd = part.startsWith('**') &&
      part.endsWith('**');
    var isItalicMd = !isBoldMd &&
      part.startsWith('*') && part.endsWith('*');
    if (isBoldMd) {
      runs += '<w:r><w:rPr><w:b/><w:bCs/></w:rPr>' +
        '<w:t xml:space="preserve">' +
        esc(part.slice(2, -2)) +
        '</w:t></w:r>';
    } else if (isItalicMd) {
      runs += '<w:r><w:rPr><w:i/><w:iCs/></w:rPr>' +
        '<w:t xml:space="preserve">' +
        esc(part.slice(1, -1)) +
        '</w:t></w:r>';
    } else {
      var rPr = forceBold
        ? '<w:rPr><w:b/><w:bCs/></w:rPr>'
        : '';
      runs += '<w:r>' + rPr +
        '<w:t xml:space="preserve">' +
        esc(part) + '</w:t></w:r>';
    }
  }
  return runs;
}

function wp(text, opts) {
  if (!opts) opts = {};
  var pPr = '';
  if (opts.heading) {
    pPr += '<w:pStyle w:val="' +
      opts.heading + '"/>';
  }
  var jc = 'both';
  if (opts.center) {
    jc = 'center';
  } else if (
    opts.heading === 'Heading2' ||
    opts.heading === 'Heading3'
  ) {
    jc = 'left';
  }
  pPr += '<w:jc w:val="' + jc + '"/>';
  var aft = opts.after || '100';
  pPr += '<w:spacing w:line="480"' +
    ' w:lineRule="auto"' +
    ' w:before="0"' +
    ' w:after="' + aft + '"/>';
  if (opts.pageBreak) {
    pPr += '<w:pageBreakBefore/>';
  }
  if (opts.hangIndent) {
    pPr += '<w:ind w:left="720"' +
      ' w:hanging="720"/>';
  }
  if (opts.bullet) {
    pPr += '<w:numPr>' +
      '<w:ilvl w:val="0"/>' +
      '<w:numId w:val="1"/>' +
      '</w:numPr>';
  }
  var content = '';
  if (text) {
    content = makeRuns(text, opts.bold);
  }
  return '<w:p><w:pPr>' + pPr +
    '</w:pPr>' + content + '</w:p>';
}

function emptyP(n) {
  var result = '';
  for (var i = 0; i < n; i++) {
    result += wp('');
  }
  return result;
}

// --- Get input ---
var raw = $('Final Assembler')
  .first().json.assembledDocument;

// --- Section parsers ---
function getSec(marker) {
  var pattern = '\\[SECTION:\\s*' + marker +
    '\\s*\\]([\\s\\S]*?)(?=' +
    '\\[SECTION:|\\[ABSTRACT\\]|' +
    '\\[REFERENCES\\]|# CHAPTER|$)';
  var re = new RegExp(pattern, 'i');
  var m = raw.match(re);
  if (!m) return '';
  var content = m[1];
  var cleanRe = new RegExp(
    '^\\s*' + marker + '\\s*', 'i'
  );
  return content.replace(cleanRe, '').trim();
}

function getMark(marker) {
  var pattern = '\\[' + marker +
    '\\]([\\s\\S]*?)(?=' +
    '\\[VERIFICATION_REPORT\\]|' +
    '\\[SECTION:|# CHAPTER|$)';
  var re = new RegExp(pattern, 'i');
  var m = raw.match(re);
  return m ? m[1].trim() : '';
}

// --- Content parser ---
function parseTxt(text, opts) {
  if (!opts) opts = {};
  var xml = '';
  var cur = '';
  var lines = text.split('\n');

  function flush() {
    if (cur) {
      xml += wp(cur, {
        center: opts.centered,
        bold: opts.allBold
      });
      cur = '';
    }
  }

  for (var i = 0; i < lines.length; i++) {
    var t = lines[i].trim();
    if (t === '' || t === '---' || t === '***') {
      flush();
      continue;
    }
    if (t.indexOf('[SECTION:') === 0 ||
        t.indexOf('[ABSTRACT') === 0 ||
        t.indexOf('[REFERENCES') === 0 ||
        t.indexOf('[VERIFICATION') === 0) {
      flush();
      continue;
    }
    if (t.indexOf('#### ') === 0) {
      flush();
      xml += wp(t.replace(/^#+\s*/, ''), {
        bold: true, heading: 'Heading3'
      });
      continue;
    }
    if (t.indexOf('### ') === 0) {
      flush();
      xml += wp(t.replace(/^#+\s*/, ''), {
        bold: true, heading: 'Heading3'
      });
      continue;
    }
    if (t.indexOf('## ') === 0) {
      flush();
      xml += wp(t.replace(/^#+\s*/, ''), {
        bold: true, heading: 'Heading2'
      });
      continue;
    }
    if (t.indexOf('# ') === 0) {
      flush();
      xml += wp(t.replace(/^#+\s*/, ''), {
        bold: true, center: true,
        heading: 'Heading1'
      });
      continue;
    }
    if (/^[-\u2022]\s+/.test(t)) {
      flush();
      xml += wp(
        t.replace(/^[-\u2022]\s+/, ''),
        { bullet: true }
      );
      continue;
    }
    if (/^\d+\.\s+/.test(t)) {
      flush();
      xml += wp(
        t.replace(/^\d+\.\s+/, '')
      );
      continue;
    }
    if (t.indexOf('|') === 0) {
      flush();
      continue;
    }
    cur = cur ? cur + ' ' + t : t;
  }
  flush();
  return xml;
}

// --- SECTION 1: Preliminary pages ---
var sec1 = '';

// Cover page
var coverText = getSec('COVER PAGE');
if (coverText) {
  sec1 += emptyP(3);
  sec1 += parseTxt(coverText, {
    centered: true, allBold: true
  });
} else {
  sec1 += emptyP(4);
  sec1 += wp('ASSESSMENT OF RADIOGRAPHY ' +
    'STUDENTS\u2019 KNOWLEDGE ON ' +
    'JUSTIFICATION CRITERIA FOR ' +
    'INTRAVENOUS UROGRAPHY (IVU) ' +
    'USING CONVENTIONAL X-RAYS ' +
    'VERSUS CT IMAGING', {
    bold: true, center: true
  });
  sec1 += emptyP(4);
  sec1 += wp('DEPARTMENT OF RADIOGRAPHY', {
    bold: true, center: true
  });
  sec1 += wp('FACULTY OF ALLIED HEALTH SCIENCES', {
    bold: true, center: true
  });
  sec1 += wp('BAYERO UNIVERSITY, KANO', {
    bold: true, center: true
  });
  sec1 += emptyP(6);
  sec1 += wp('JUNE 2025', {
    bold: true, center: true
  });
}

// Title page
var titleText = getSec('TITLE PAGE');
if (titleText) {
  sec1 += wp('', { pageBreak: true });
  sec1 += parseTxt(titleText, {
    centered: true, allBold: true
  });
} else {
  sec1 += wp('TITLE PAGE', {
    bold: true, center: true,
    pageBreak: true
  });
}

// Certification
sec1 += wp('CERTIFICATION', {
  bold: true, center: true,
  heading: 'Heading1', pageBreak: true
});
var certText = getSec('CERTIFICATION');
if (certText) {
  sec1 += parseTxt(
    certText.replace(/^CERTIFICATION\s*/i, '')
  );
}

// Approval
var apprText = getSec('APPROVAL');
if (apprText) {
  sec1 += wp('APPROVAL', {
    bold: true, center: true,
    heading: 'Heading1', pageBreak: true
  });
  sec1 += parseTxt(
    apprText.replace(/^APPROVAL\s*(PAGE)?\s*/i, '')
  );
}

// Dedication
var dedText = getSec('DEDICATION');
if (dedText) {
  sec1 += wp('DEDICATION', {
    bold: true, center: true,
    heading: 'Heading1', pageBreak: true
  });
  sec1 += parseTxt(
    dedText.replace(/^DEDICATION\s*/i, '')
  );
}

// Acknowledgement
var ackText = getSec('ACKNOWLEDGEMENT');
if (ackText) {
  sec1 += wp('ACKNOWLEDGEMENT', {
    bold: true, center: true,
    heading: 'Heading1', pageBreak: true
  });
  sec1 += parseTxt(
    ackText.replace(/^ACKNOWLEDGEMENT\s*/i, '')
  );
}

// Table of Contents
sec1 += wp('TABLE OF CONTENTS', {
  bold: true, center: true,
  heading: 'Heading1', pageBreak: true
});
sec1 += wp(
  '(Right-click > Update Field in Word)',
  { center: true }
);

// List of Tables
sec1 += wp('LIST OF TABLES', {
  bold: true, center: true,
  heading: 'Heading1', pageBreak: true
});
var lotText = getSec('LIST OF TABLES');
if (lotText) {
  sec1 += parseTxt(
    lotText.replace(/^LIST OF TABLES\s*/i, '')
  );
}

// List of Figures
sec1 += wp('LIST OF FIGURES', {
  bold: true, center: true,
  heading: 'Heading1', pageBreak: true
});
var lofText = getSec('LIST OF FIGURES');
if (lofText) {
  sec1 += parseTxt(
    lofText.replace(/^LIST OF FIGURES\s*/i, '')
  );
}

// List of Abbreviations
sec1 += wp('LIST OF ABBREVIATIONS', {
  bold: true, center: true,
  heading: 'Heading1', pageBreak: true
});
var loaText = getSec('LIST OF ABBREVIATIONS');
if (loaText) {
  sec1 += parseTxt(
    loaText.replace(/^LIST OF ABBREVIATIONS\s*/i,'')
  );
}

// Abstract
sec1 += wp('ABSTRACT', {
  bold: true, center: true,
  heading: 'Heading1', pageBreak: true
});
var absText = getMark('ABSTRACT');
if (absText) {
  var absCur = '';
  var absLines = absText.split('\n');
  for (var ai = 0; ai < absLines.length; ai++) {
    var at = absLines[ai].trim();
    if (at === '' || at === '---' || at === '***') {
      if (absCur) {
        sec1 += wp(absCur);
        absCur = '';
      }
      continue;
    }
    absCur = absCur ? absCur + ' ' + at : at;
  }
  if (absCur) sec1 += wp(absCur);
}

// --- SECTION 2: Chapters + References ---
var sec2 = '';

// Chapter 1
var ch1S = raw.indexOf('# CHAPTER ONE');
var ch2S = raw.search(
  /## (Chapter 2|2\.0 INTRODUCTION)/i
);
if (ch1S > -1) {
  var ch1End = ch2S > -1 ? ch2S : raw.length;
  var ch1 = raw.substring(ch1S, ch1End).trim();
  ch1 = ch1.replace(
    /^# CHAPTER ONE:?\s*(INTRODUCTION)?\s*\n*/i,
    ''
  );
  sec2 += wp('CHAPTER ONE', {
    bold: true, center: true,
    heading: 'Heading1'
  });
  sec2 += wp('INTRODUCTION', {
    bold: true, center: true, after: '200'
  });
  sec2 += parseTxt(ch1);
}

// Chapter 2
var ch3S = raw.search(
  /# CHAPTER THREE|### 3\.1 RESEARCH DESIGN/i
);
if (ch2S > -1 && ch3S > -1) {
  var ch2 = raw.substring(ch2S, ch3S).trim();
  var ri1 = ch2.lastIndexOf('### References');
  if (ri1 > -1) ch2 = ch2.substring(0, ri1).trim();
  var ri2 = ch2.lastIndexOf('## References');
  if (ri2 > -1) ch2 = ch2.substring(0, ri2).trim();
  ch2 = ch2.replace(
    /^##?\s*Chapter\s*(Two|2):?\s*(LITERATURE\s*REVIEW)?\s*\n*/i,
    ''
  );
  ch2 = ch2.replace(
    /^##?\s*2\.0\s*INTRODUCTION/i,
    '## 2.0 INTRODUCTION'
  );
  sec2 += wp('CHAPTER TWO', {
    bold: true, center: true,
    heading: 'Heading1', pageBreak: true
  });
  sec2 += wp('LITERATURE REVIEW', {
    bold: true, center: true, after: '200'
  });
  sec2 += parseTxt(ch2);
}

// Chapter 3
if (ch3S > -1) {
  var r1 = raw.indexOf('[REFERENCES]', ch3S);
  var r2 = raw.indexOf(
    '**References** (for methodology', ch3S
  );
  var ch3End = raw.length;
  if (r1 > -1 && r1 < ch3End) ch3End = r1;
  if (r2 > -1 && r2 < ch3End) ch3End = r2;
  var ch3 = raw.substring(ch3S, ch3End).trim();
  ch3 = ch3.replace(
    /^# CHAPTER THREE:?\s*(METHODOLOGY)?\s*\n*/i,
    ''
  );
  ch3 = ch3.replace(/^## METHODOLOGY\s*\n*/i, '');
  ch3 = ch3.replace(
    /^### (\d+\.\d+ )/gm, '## $1'
  );
  ch3 = ch3.replace(
    /^#### (\d+\.\d+\.\d+ )/gm, '### $1'
  );
  sec2 += wp('CHAPTER THREE', {
    bold: true, center: true,
    heading: 'Heading1', pageBreak: true
  });
  sec2 += wp('METHODOLOGY', {
    bold: true, center: true, after: '200'
  });
  sec2 += parseTxt(ch3);
}

// References
sec2 += wp('REFERENCES', {
  bold: true, center: true,
  heading: 'Heading1', pageBreak: true
});
var refsRaw = getMark('REFERENCES');
if (refsRaw) {
  var allRefs = refsRaw;
  var methIdx = raw.lastIndexOf(
    '**References** (for methodology'
  );
  if (methIdx > -1) {
    var methBlock = raw.substring(methIdx);
    var methLines = methBlock.split('\n').filter(
      function(l) {
        return l.trim().indexOf('- ') === 0;
      }
    );
    allRefs += '\n' + methLines.map(function(l) {
      return l.replace(/^- /, '').trim();
    }).join('\n');
  }

  var refEntries = [];
  var rce = '';
  var refLines = allRefs.split('\n');
  for (var ri = 0; ri < refLines.length; ri++) {
    var rt = refLines[ri].trim();
    if (rt === '' || rt === '---' ||
        rt === '***' ||
        rt.indexOf('[Note:') === 0 ||
        rt.indexOf('[VERIFICATION') === 0) {
      if (rce) {
        refEntries.push(rce.trim());
        rce = '';
      }
      continue;
    }
    var startsWithAuthor = /^[A-Z][a-z\u00C0-\u024F]/.test(rt);
    if (startsWithAuthor && rce &&
        rt.indexOf('http') !== 0) {
      refEntries.push(rce.trim());
      rce = rt;
    } else {
      rce = rce ? rce + ' ' + rt : rt;
    }
  }
  if (rce) refEntries.push(rce.trim());

  var seen = {};
  var unique = [];
  for (var ui = 0; ui < refEntries.length; ui++) {
    var c = refEntries[ui]
      .replace(/\*\*/g, '')
      .replace(/\*/g, '')
      .trim();
    if (!c || c.length < 10) continue;
    var key = c.substring(0, 50).toLowerCase();
    if (!seen[key]) {
      seen[key] = true;
      unique.push(c);
    }
  }
  unique.sort(function(a, b) {
    return a.localeCompare(b, undefined, {
      sensitivity: 'base'
    });
  });

  for (var xi = 0; xi < unique.length; xi++) {
    sec2 += wp(unique[xi], {
      hangIndent: true, after: '120'
    });
  }
}

